1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Out;
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	public class BuildOwner {
15	
16	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
17	            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
18	        Owner owner = ownerMapper.toOwner(request);
19	        // The effective registration date defaults an unsupplied value to the server's
20	        // current date, then rolls any weekend forward to the next Monday so derived values
21	        // (e.g. the membership number's year) use the adjusted business day.
22	        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
23	        owner.setCustomerCode(customerCode(owner));
24	        // Record how many existing owners already share this first+last name (case-insensitive),
25	        // counted before this owner is persisted so the value is fixed at creation time.
26	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
27	        // Join a shared household when the gate resolved an identifier.
28	        if (householdId != null && householdId.isPresent()) {
29	            owner.setHouseholdId(householdId.value());
30	        }
31	        built.set(owner);
32	    }
33	
34	    /**
35	     * Build the '<REGION>-<HASH8>' customer code: REGION is the region derived from the owner's
36	     * postcode and city ({@link Owner#regionFor(String, String)}, e.g. 'NSW' or 'UNKNOWN'), and
37	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 of the normalized telephone
38	     * followed by the last name (e.g. 'NSW-1A2B3C4D'). There is no sequence number, so the code
39	     * is stable for an owner regardless of creation order.
40	     */
41	    private static String customerCode(Owner owner) {
42	        String region = Owner.regionFor(owner.getPostcode(), owner.getCity());
43	        String normalizedTelephone = OwnerTelephone.normalize(owner.getTelephone());
44	        String seed = (normalizedTelephone == null ? "" : normalizedTelephone) + owner.getLastName();
45	        return region + "-" + hash8(seed);
46	    }
47	
48	    /**
49	     * The first 8 upper-case hex characters of the SHA-256 of the UTF-8 bytes of {@code seed}.
50	     */
51	    private static String hash8(String seed) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder(8);
56	            for (int i = 0; i < 4; i++) {
57	                sb.append(String.format("%02X", digest[i]));
58	            }
59	            return sb.toString();
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 not available", ex);
63	        }
64	    }
65	
66	    /**
67	     * Count the existing owners whose first and last names both match the given names,
68	     * compared case-insensitively.
69	     */
70	    private static int countNamesakes(String firstName, String lastName,
71	            OwnerRepository ownerRepository) {
72	        int count = 0;
73	        for (Owner existing : ownerRepository.findAll()) {
74	            if (firstName.equalsIgnoreCase(existing.getFirstName())
75	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
76	                count++;
77	            }
78	        }
79	        return count;
80	    }
81	}
